CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,name TEXT NOT NULL,date TEXT NOT NULL,location TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS one_active ON events(active) WHERE active=1;
CREATE TABLE IF NOT EXISTS registrations(id INTEGER PRIMARY KEY,event_id INTEGER NOT NULL REFERENCES events,company TEXT NOT NULL,name TEXT NOT NULL,phone TEXT NOT NULL,token TEXT UNIQUE NOT NULL,created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,telegram TEXT NOT NULL DEFAULT 'pendente',UNIQUE(event_id,phone));
CREATE TABLE IF NOT EXISTS certificates(registration_id INTEGER PRIMARY KEY REFERENCES registrations,template_version TEXT,pdf_path TEXT,issued_at TEXT);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS limits(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
